def solve(g):
    from collections import Counter
    h,w=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    # separator color: second most common forming lines
    cnt=Counter(v for r in g for v in r)
    sep=[c for c,_ in cnt.most_common() if c!=bg][0]
    def issep_row(r): return sum(1 for v in g[r] if v==sep) > w//2
    def issep_col(c): return sum(1 for r in range(h) if g[r][c]==sep) > h//2
    sr=[r for r in range(h) if issep_row(r)]
    sc=[c for c in range(w) if issep_col(c)]
    out=[]
    for a,b in zip(sr,sr[1:]):
        row=[]
        for x,y in zip(sc,sc[1:]):
            vals={g[a][x],g[a][y],g[b][x],g[b][y]}
            ok=True
            for v in [g[a][x],g[a][y],g[b][x],g[b][y]]:
                if v==bg or v==sep: ok=False
            if ok and len(vals)==1: row.append(list(vals)[0])
            else: row.append(bg)
        out.append(row)
    return out
